const config = {};

for (const item of $input.all()) {
  const f = item.json.fields || item.json;
  config[f.Clave] = f.Valor;
}

config.duracion_turno_min = Number(config.duracion_turno_min);
config.dias_busqueda_alternativa = Number(config.dias_busqueda_alternativa);

return [{ json: config }];

const ZONA = 'America/Argentina/Buenos_Aires';
const nombresDia = ['', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];

// Solo eventos reales (ignora el item vacío cuando la agenda no tiene nada)
const ocupados = $input.all()
  .map(i => i.json)
  .filter(e => e.start && (e.start.dateTime || e.start.date))
  .map(e => ({
    inicio: e.start.dateTime || e.start.date,
    fin: e.end.dateTime || e.end.date,
  }));

const cfg = $('Armar Configuración').first().json;
const form = $('Formulario Solicitud Turno').first().json;
const turno = $('Crear Turno').first().json;

// Días de atención desde la configuración (1 = lunes ... 7 = domingo)
const diasAtencion = String(cfg.dias_atencion).split(',').map(d => Number(d.trim()));

const fechaSolicitada = DateTime.fromISO(
  `${form['Fecha Preferida']}T${form['Horario Preferido']}:00`,
  { zone: ZONA }
);

// Lista de días válidos para proponer (ya sin fines de semana)
const diasDisponibles = [];
for (let i = 0; i <= cfg.dias_busqueda_alternativa; i++) {
  const d = fechaSolicitada.startOf('day').plus({ days: i });
  if (diasAtencion.includes(d.weekday)) {
    diasDisponibles.push(`${d.toISODate()} (${nombresDia[d.weekday]})`);
  }
}

return [{
  json: {
    turno_id: turno.id,
    paciente: form.nombre,
    motivo: form.Motivo,
    fecha_solicitada: fechaSolicitada.toISO(),
    dia_semana_solicitado: nombresDia[fechaSolicitada.weekday],
    dia_solicitado_es_de_atencion: diasAtencion.includes(fechaSolicitada.weekday),
    dias_de_atencion_disponibles: diasDisponibles.join(', '),
    hora_inicio_atencion: cfg.hora_inicio_atencion,
    hora_fin_atencion: cfg.hora_fin_atencion,
    duracion_turno_min: cfg.duracion_turno_min,
    dias_busqueda_alternativa: cfg.dias_busqueda_alternativa,
    cantidad_ocupados: ocupados.length,
    ocupados: JSON.stringify(ocupados),
  },
}];

